"""Import invoice records from the legacy tsv v1 format."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable, Iterator, List, Optional

from ..money import Money

DELIMITER = None
RECORD_KIND = "invoice"
SKIP_PREFIXES = ("#", "//", "REM ")
MAX_FIELD_LENGTH = 512


class LegacyTsvV1ParseError(ValueError):
    """Raised when a line cannot be understood as a invoice record."""

    def __init__(self, line_number: int, message: str) -> None:
        super().__init__("line {0}: {1}".format(line_number, message))
        self.line_number = line_number


@dataclass
class LegacyTsvV1Record:
    line_number: int
    reference: str
    amount: Money
    description: str = ""

    def is_credit(self) -> bool:
        return self.amount.cents > 0

    def is_debit(self) -> bool:
        return self.amount.cents < 0


def _should_skip(line: str) -> bool:
    stripped = line.strip()
    if not stripped:
        return True
    return any(stripped.startswith(prefix) for prefix in SKIP_PREFIXES)


def split_fields(line: str) -> List[str]:
    """Split one raw line into its fields."""
    if DELIMITER is None:
        return [chunk for chunk in line.split() if chunk]
    return [chunk.strip() for chunk in line.split(DELIMITER)]


def parse_line(line_number: int, line: str) -> Optional[LegacyTsvV1Record]:
    """Parse one line, or return None when the line should be skipped."""
    if _should_skip(line):
        return None
    fields = split_fields(line)
    if len(fields) < 2:
        raise LegacyTsvV1ParseError(line_number, "expected at least two fields")
    reference = fields[0][:MAX_FIELD_LENGTH]
    try:
        amount = Money.from_str(fields[1])
    except Exception as exc:
        raise LegacyTsvV1ParseError(line_number, "bad amount: " + str(exc)) from exc
    description = fields[2][:MAX_FIELD_LENGTH] if len(fields) > 2 else ""
    return LegacyTsvV1Record(line_number=line_number, reference=reference,
                       amount=amount, description=description)


def parse(lines: Iterable[str]) -> Iterator[LegacyTsvV1Record]:
    """Parse an iterable of lines into invoice records."""
    for number, line in enumerate(lines, start=1):
        record = parse_line(number, line)
        if record is not None:
            yield record


def totals(records: Iterable[LegacyTsvV1Record]) -> Money:
    """Sum the amounts of every record."""
    total = Money(0)
    for record in records:
        total = total + record.amount
    return total

